"""Add document routes and evidence reading guides to the sourced dataset."""
import json
from pathlib import Path

ROOT = Path(__file__).parent

def enrich(d):
    official = json.loads((ROOT / 'processos-oficiais.json').read_text(encoding='utf-8-sig'))['processos']
    def source(key, title, url, kind='Consulta processual oficial', date='Consulta em 28/10/2026'):
        d['sources'][key] = dict(title=title, url=url, kind=kind, date=date)
    for i,p in enumerate(official):
        source('autos'+str(i),p['titulo'],p['url'], 'Documento judicial oficial' if p.get('tipo') in ['decisao_pdf','acordao_oficial','decisao_oficial'] else 'Consulta processual oficial')
    source('rclportal','STF · RCL 43.007 · consulta processual','https://portal.stf.jus.br/processos/detalhe.asp?incidente=5990778')
    source('hcforo','STF · HC 193.726 · competência dos processos de Lula','https://portal.stf.jus.br/processos/detalhe.asp?incidente=6043118')
    d['sources']['toffoli'].update(url=official[2]['url'],kind='Decisão judicial — PDF oficial do STF')
    d['cases']={
        'Sítio':dict(title='Sítio Santa Bárbara, Atibaia',number='5021365-32.2017.4.04.7000',court='Justiça Federal / TRF4; decisões posteriores do STF',portal='autos0',documents=['sitiosent','sitioden'],rulings=['hcforo','autos3','autos4'],chapters=[2,6],note='A consulta do TRF4 é a tramitação histórica. A condenação de Lula foi anulada e o caso seguiu para Brasília. Uma consulta pública não garante acesso a todas as peças; alguns eventos podem exigir login.'),
        'Triplex':dict(title='Triplex do Guarujá',number='5046512-94.2016.4.04.7000',court='Justiça Federal / TRF4; decisões posteriores do STF',portal='autos1',documents=['triplexsent','mpfpre'],rulings=['hcforo','autos3'],chapters=[3,6],note='A página do TRF4 registra a tramitação histórica. A sentença não é uma condenação vigente: houve anulação e, depois, prescrição. A cópia da sentença é oferecida separadamente da consulta oficial.'),
        'Odebrecht':dict(title='Sistemas e acordo da Odebrecht',number='RCL 43.007 / DF · 0101589-48.2020.1.00.0000',court='Supremo Tribunal Federal',portal='rclportal',documents=['toffoli','sistemas','anpr','dojdoc'],rulings=['autos2'],chapters=[4,5],note='A reclamação trata do acesso e da utilização das provas; não é a ação penal do sítio. No portal do STF, consulte Andamentos e Decisões. O PDF oficial de 06/09/2023 está disponível separadamente.'),
        'Instituto':dict(title='Instituto Lula e controvérsia probatória',number='Ação de origem 5063130-17.2016.4.04.7000 · RCL 43.007 / DF',court='Justiça Federal; reclamação no STF',portal='rclportal',documents=['ilacus','toffoli'],rulings=['instituto','autos2'],chapters=[5,6],note='O link final abre a RCL 43.007, decisão conexa sobre o material probatório. Não se apresenta essa reclamação como se fosse a íntegra de todas as ações sobre sede e doações.'),
        'Dirceu':dict(title='José Dirceu · Engevix / JD',number='5045241-84.2015.4.04.7000 · PET 12.229 / DF · REsp 1.774.165 / PR',court='Justiça Federal / STF / STJ',portal='autos5',documents=['autos6','autos7','autos8'],rulings=['autos5','autos7'],chapters=[7],note='A PET 12.229 é o processo do STF sobre anulação dos atos. O REsp 1.774.165 é o recurso no STJ, com documento oficial próprio. Esses autos não são o mensalão nem a ação Apolo Tubulars.')
    }
    guides={
      'E01':('Como separar dono, frequentador e beneficiário?', 'Comece pelos nomes na matrícula do imóvel: esse é o registro de propriedade. Depois examine os registros de uso e o que cada testemunha presenciou. Por último, separe quem autorizou, quem pagou e quem aproveitou cada reforma. A tese contra Lula não dependia de uma escritura em seu nome: sustentava que ele recebeu benefícios nas obras. Por isso, a ausência do nome na matrícula e a presença da família no sítio respondem a perguntas diferentes. Na leitura dos autos, procure Bittar, Suassuna, utilização e benfeitorias.'),
      'E02':('O que preciso conferir em cada recibo?', 'Confira a data, o fornecedor, o produto ou serviço, o endereço de entrega, o nome do comprador e o comprovante de pagamento. Esses campos podem apontar para pessoas distintas. A notícia sobre a apreensão informa onde os papéis estavam; ela não oferece, por si só, a auditoria bancária de cada compra. Os cerca de R$ 66,1 mil referem-se ao conjunto descrito na reportagem, e não a um valor adicional que possa ser somado automaticamente ao custo das reformas. Procure o recibo individual nos anexos antes de atribuir uma transferência específica a alguém.'),
      'E03':('Onde o depoimento do engenheiro entra na cadeia?', 'Há três ligações a examinar: o dinheiro entregue ao responsável pela obra; o serviço efetivamente executado; e a alegada aceitação da vantagem pelo beneficiário. Emyr descreveu a frente da Odebrecht e recursos em espécie. Emílio aparece em outro papel: a decisão empresarial e a conversa que atribuiu a Lula. São relatos de pessoas diferentes sobre etapas diferentes. Um pagamento em espécie deve ser cruzado com compras, fornecedores, datas e instruções, sem transformar o valor aproximado do depoimento numa transferência bancária documentada.'),
      'E04':('Por que a cozinha não é a mesma prova dos sistemas?', 'OAS e Odebrecht são empresas diferentes. A discussão sobre cozinha e equipamentos envolve contratação, execução, comunicações e relatos atribuídos a Paulo Gordilho e Léo Pinheiro. Drousys e MyWebDay B pertenciam à estrutura da Odebrecht. Portanto, é preciso identificar a origem de cada documento antes de aplicar o carimbo de prova invalidada. A sentença pode ter sido anulada por problemas do processo sem que o motivo seja a origem digital de uma nota da OAS. Procure cozinha, Gordilho, OAS e o fornecedor no material do sítio.'),
      'E05':('O que aconteceu com a acusação contra Bumlai?', 'A denúncia e o resultado do julgamento precisam ser lidos separadamente. O MPF descreveu a frente de obras associada a Bumlai. No julgamento do TRF4 em 27/11/2019, Bumlai foi absolvido da imputação de lavagem de dinheiro. Portanto, sua presença neste fio não significa uma condenação vigente, nem autoriza dizer que o processo apenas terminou por anulação. O mapa conserva a participação alegada na obra e identifica o desfecho individual. Consulte também a seção Outros réus da notícia oficial, como roteiro para localizar o acórdão.'),
      'E06':('Como cruzar datas sem inventar uma ligação?', 'Monte uma sequência com a data da mensagem, a data da viagem, a ordem ao fornecedor e a execução da obra. Anote também quem produziu cada registro e se ele é contemporâneo aos fatos ou uma lembrança em depoimento. Uma viagem pode situar alguém numa cidade, mas não reproduz o que foi dito numa reunião. Mensagens podem mostrar uma instrução, mas precisam do contexto anterior e posterior. Esta ficha reúne categorias de material; não afirma que todos os anexos de cada categoria tenham sido individualmente autenticados neste trabalho.'),
      'E07':('O que a perícia resolveu sobre a rasura?', 'O documento contém referências a unidades do empreendimento. A sentença descreveu a alteração de 174 para 141 e discutiu um termo sem assinatura. Identificar uma alteração no papel é diferente de identificar seu autor, sua data e sua finalidade. A leitura acusatória relacionou a referência ao triplex à destinação do imóvel. A leitura defensiva precisa ser examinada à luz da opção de compra e da desistência alegada. A perícia descrita não determinou autoria e momento exato da alteração; não complete essa lacuna com uma conclusão que o laudo não oferece.'),
      'E08':('Que etapas ligariam uma visita ao recebimento de vantagem?', 'A sequência a investigar é: reserva comercial, visita, escolha de modificações, contratação da reforma, pagamento e efetiva disponibilidade do imóvel. A acusação leu o conjunto como adaptação para o casal; Lula afirmou que não concluiu a aquisição. Uma visita isolada é compatível com avaliar uma compra. O argumento acusatório dependia de algo além dela, como a destinação e o custeio das intervenções. Na sentença histórica, compare o tratamento das planilhas, das comunicações e dos depoimentos com a resposta da defesa, em vez de ler somente a conclusão.'),
      'E09':('Qual foi o percurso do arquivo até o juiz?', 'Os sistemas eram da Odebrecht, não do tribunal. O percurso probatório envolve obter uma cópia dos servidores, registrar quem a entregou e recebeu, preservar a mídia, analisar os dados e permitir o contraditório. A RCL 43.007 discutiu inicialmente o acesso da defesa. A decisão de 06/09/2023 tratou da utilização do material dos sistemas, com fundamentos sobre obtenção, integridade e atuação processual. A ANPR contestou a leitura da cooperação internacional e apontou pedido formal e perícia. Os detalhes de cada posição aparecem nos ramos abaixo; este dossiê não examinou as mídias originais.'),
      'E10':('Terreno, sede e doações são o mesmo fato?', 'Não. Uma aquisição imobiliária proposta para sede e repasses registrados como doações são operações diferentes. A acusação procurou relacioná-las a vantagens indevidas; o Instituto é a entidade, não o próprio terreno. Ao seguir Odebrecht → Instituto → Lula, leia o que cada fio afirma: pagamento alegado, vínculo institucional ou decisão judicial. A notícia do STF sobre o encerramento de ações explica o resultado de 2023. A RCL 43.007 fornece o contexto da controvérsia probatória, mas não substitui os autos de todas as ações reunidas nesta ficha.'),
      'E11':('A admissão da empresa condenou os políticos do quadro?', 'O documento norte-americano registra a posição e as obrigações da empresa naquele procedimento. Ele ajuda a entender a estrutura empresarial e os mecanismos de pagamentos. Para atribuir um crime a uma pessoa específica, porém, é necessário conferir se ela é individualmente identificada, qual conduta é descrita e o que foi efetivamente julgado. O acordo corporativo não substitui uma sentença brasileira contra Lula. Neste ramo, a última etapa oferece o documento original do Departamento de Justiça dos Estados Unidos; o portal do STF é um caminho separado, relativo às provas brasileiras.'),
      'E12':('Como distinguir Engevix → JD de Engevix → Jamp?', 'JD Consultoria é a empresa associada a Dirceu. Jamp é a empresa ligada a Milton Pascowitch, citado como intermediário na narrativa acusatória. São destinatários distintos: para cada repasse, seria necessário identificar contrato, nota, data, valor e serviço alegado. O mapa resume esses caminhos sem inventar uma transferência única entre as pontas. O vínculo político Dirceu → Lula é outro fio e não prova que Lula recebeu os valores dessa ação. Para o desfecho, consulte a PET 12.229 no STF e o REsp 1.774.165 no STJ, que têm objetos próprios.')
    }
    for e in d['evidence']:
        e['guide']=dict(title=guides[e['id']][0],text=guides[e['id']][1])
    for id,extra in [('E03','Emyr foi absolvido pelo TRF4 em 27/11/2019 por insuficiência de prova da ciência sobre lavagem de capital ilícito.'),('E04','Paulo Gordilho foi absolvido pelo TRF4 em 27/11/2019. O resultado individual não deve ser confundido com a condenação então mantida de outros réus.'),('E05','Bumlai foi absolvido da lavagem pelo TRF4 em 27/11/2019; não deve ser apresentado como alguém cuja única saída foi a anulação do processo.')]:
        e=next(x for x in d['evidence'] if x['id']==id)
        e['status']=extra+' '+e['status']
        e['sources']=list(dict.fromkeys(e['sources']+['sitiotrf']))
    d['evidence'][8]['sources']=list(dict.fromkeys(d['evidence'][8]['sources']+['toffoli','anpr']))
    for n in d['nodes']:
        if n['id']=='instituto':n['asset']='instituto_context'
        if n['id']=='bumlai':n['desc']+=' No processo do sítio, o TRF4 o absolveu da imputação de lavagem em 2019.'
    for e in d['edges']:
        if e['id']=='R07':
            e['detail']+=' No julgamento de 27/11/2019, Bumlai foi absolvido da lavagem pelo TRF4. A frente de obras alegada e o resultado penal individual são informações distintas.'
            e['sources']=list(dict.fromkeys(e['sources']+['sitiotrf']))
    return d

if __name__=='__main__':
    import conteudo
    data=conteudo.data
    data['custody']=json.loads((ROOT/'pesquisa-dirceu.json').read_text(encoding='utf-8-sig'))['custodia']
    (ROOT/'dados.json').write_text(json.dumps(enrich(data),ensure_ascii=False,indent=2),encoding='utf-8')
